55	// What MHPCO insures each item for, as distinct from what it charges to do so.
56	const INSURANCE_VALUES: Record<string, number> = {
57	  sword: 1000,
58	  amulet: 600,
59	  staff: 800,
60	  potion: 400,
61	  rune: 250,
62	  moonstone: 250,
63	};
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
75	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
76	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
77	// (100 * 110) / 100 is exact.
78	const ONE_HUNDRED_PERCENT = 100;
79	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
80	const ADMIN_FEE = 5;
81	const LOYALTY_YEARS = 2;
82	const LOYALTY_DISCOUNT_PERCENT = 20;
83	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLE = 2;
86	const NO_PAYOUT = 0;
87	const PERILOUS_ENCHANTMENT = 8;
88	const PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
89	const FULL_REIMBURSEMENT_PERCENT = 100;
90	const DRAGON_MATERIAL = "dragon";
91	
92	const applyPercent = (amount: number, percent: number): number =>
93	  (amount * percent) / ONE_HUNDRED_PERCENT;
94	
95	const addSurcharge = (amount: number, surchargePercent: number): number =>
96	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
97	
98	const applyDiscount = (amount: number, discountPercent: number): number =>
99	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
100	
101	const COMPONENT_TYPES = ["rune", "moonstone"];
102	const BUILDING_BLOCK_SIZE = 3;
103	const BUILDING_BLOCK_BASE_PREMIUM = 60;
104	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
105	
106	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
107	
108	// Both the per-item risk surcharges and the contract-level modifiers are lists
109	// of the same kind of thing: an adjustment to an amount, guarded by a condition
110	// on some subject. They stack multiplicatively — each adjustment applies to the
111	// result of the one before — so both are applied by the same fold, and the two
112	// lists cannot drift apart in how they combine.
113	interface Adjustment<Subject> {
114	  appliesTo: (subject: Subject) => boolean;
115	  adjust: (amount: number) => number;
116	}
117	
118	const adjusted = <Subject,>(
119	  amount: number,
120	  subject: Subject,
121	  adjustments: Adjustment<Subject>[],
122	): number =>
123	  adjustments.reduce(
124	    (running, adjustment) =>
125	      adjustment.appliesTo(subject) ? adjustment.adjust(running) : running,
126	    amount,
127	  );
128	
129	// Risk surcharges are per-item properties of the insured object, each raising
130	// that item's premium by a percentage.
131	const HIGH_ENCHANTMENT = 5;
132	const NO_ENCHANTMENT = 0;
133	const CURSED_SURCHARGE_PERCENT = 50;
134	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
135	
136	const RISK_SURCHARGES: Adjustment<Item>[] = [
137	  {
138	    appliesTo: (item) => item.cursed === true,
139	    adjust: (premium) => addSurcharge(premium, CURSED_SURCHARGE_PERCENT),
140	  },
141	  {
142	    appliesTo: (item) => (item.enchantment ?? NO_ENCHANTMENT) >= HIGH_ENCHANTMENT,
143	    adjust: (premium) =>
144	      addSurcharge(premium, HIGH_ENCHANTMENT_SURCHARGE_PERCENT),
145	  },
146	];
147	
148	const riskAdjustedPremiumOf = (item: Item): number =>
149	  adjusted(basePremiumOf(item), item, RISK_SURCHARGES);
150	
151	const sumRiskAdjustedPremiums = (items: Item[]): number =>
152	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
153	
154	// Alike components are grouped into building blocks of 3, which carry a
155	// special base premium; the remaining components are priced individually,
156	// risk surcharges and all.
157	// Total over the empty group: no components means no blocks and no remainder.
158	const alikeComponentsPremium = (components: Item[]): number => {
159	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
160	  const remainingComponents = components.slice(blockCount * BUILDING_BLOCK_SIZE);
161	  return (
162	    blockCount * BUILDING_BLOCK_BASE_PREMIUM +
163	    sumRiskAdjustedPremiums(remainingComponents)
164	  );
165	};
166	
167	// Splits items into those matching the predicate and those not, in one pass,
168	// so the rule dividing them is written exactly once.
169	const partition = (
170	  items: Item[],
171	  matches: (item: Item) => boolean,
172	): [Item[], Item[]] =>
173	  items.reduce<[Item[], Item[]]>(
174	    ([matching, rest], item) =>
175	      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
176	    [[], []],
177	  );
178	
179	const groupByType = (items: Item[]): Item[][] => [
180	  ...items
181	    .reduce(
182	      (groups, item) =>
183	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
184	      new Map<string, Item[]>(),
185	    )
186	    .values(),
187	];
188	
189	// Components and main items are priced by different rules, so each group is
190	// totalled separately: components by building block, main items item by item.
191	const componentsPremium = (components: Item[]): number =>
192	  groupByType(components).reduce(
193	    (total, alike) => total + alikeComponentsPremium(alike),
194	    0,
195	  );
196	
197	// What the items alone cost to insure, before any modifier that depends on the
198	// customer or the contract they sit in. This is a premium, not a sum insured:
199	// what MHPCO *charges* for the cover, not what it will *pay out* — an amulet
200	// costs 60 here and is insured for 600 (see insuranceSumOf). Every item is
201	// either a component or a main item — the split is stated once, as a partition,
202	// so the two halves cannot drift apart — and each half is priced by its own
203	// rules.
204	const itemsPremiumOf = (items: Item[]): number => {
205	  const [components, mainItems] = partition(items, isComponent);
206	  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
207	};
208	
209	// Contract-level modifiers adjust the premium by the terms of the deal rather
210	// than the nature of the items.
211	interface Contract {
212	  customer: Customer;
213	  isFirstContract: boolean;
214	}
215	
216	// Every contract is priced on one of two standings: a first insurance is
217	// assessed a surcharge, a later one rewarded with a discount. This is a choice,
218	// not two independent rules, so it is written as one — there is no way to
219	// express a contract that gets both or neither.
220	const standingAdjustedPremiumOf = (
221	  amount: number,
222	  { isFirstContract }: Contract,
223	): number =>
224	  isFirstContract
225	    ? addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT)
226	    : applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT);
227	
228	// Modifiers that a contract may or may not earn, on top of its standing.
229	const CONTRACT_MODIFIERS: Adjustment<Contract>[] = [
230	  {
231	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
232	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
233	  },
234	];
235	
236	const contractAdjustedPremiumOf = (
237	  itemsPremium: number,
238	  contract: Contract,
239	): number =>
240	  adjusted(
241	    standingAdjustedPremiumOf(itemsPremium, contract),
242	    contract,
243	    CONTRACT_MODIFIERS,
244	  );
245	
246	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
247	// so that no percentage ever applies to it.
248	const billedPremiumOf = (premium: number): number =>
249	  Math.ceil(premium) + ADMIN_FEE;
250	
251	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
252	  premium: billedPremiumOf(
253	    contractAdjustedPremiumOf(itemsPremiumOf(step.items), contract),
254	  ),
255	});
256	
257	// The insurance sum is what the items are covered for, and it is the basis of
258	// the payout cap — unrelated to the premium charged for that cover.
259	const insuranceSumOf = (items: Item[]): number =>
260	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
261	
262	// A quote creates a policy, which then absorbs claims: every payout draws down
263	// a cap of twice the insurance sum, so the policy carries state between steps.
264	// The policy keeps the items it covers: a claim is settled by the nature of the
265	// damaged item, so the cover has to be able to look back at what it insured.
266	interface Policy {
267	  remainingCap: number;
268	  items: Item[];
269	}
270	
271	const policyFor = (items: Item[]): Policy => ({
272	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE,
273	  items,
274	});
275	
276	// How much of a damage MHPCO shoulders depends on what was damaged: an item so
277	// heavily enchanted that its own magic invites disaster is met halfway. Unlike
278	// the risk surcharges, these rules select rather than stack — an item is
279	// settled on one footing, so the first matching rule decides and the rest are
280	// not consulted. Precedence is therefore the order of this list.
281	interface ReimbursementRule {
282	  appliesTo: (item: Item) => boolean;
283	  percent: number;
284	}
285	
286	const REIMBURSEMENT_RULES: ReimbursementRule[] = [
287	  // Dragon stuff is made whole however perilously enchanted it also is, so this
288	  // rule is listed first and the perilous-enchantment rule never gets to speak.
289	  {
290	    appliesTo: (item) => item.material === DRAGON_MATERIAL,
291	    percent: FULL_REIMBURSEMENT_PERCENT,
292	  },
293	  {
294	    appliesTo: (item) =>
295	      (item.enchantment ?? NO_ENCHANTMENT) >= PERILOUS_ENCHANTMENT,
296	    percent: PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT,
297	  },
298	];
299	
300	// A damage names a type, and a policy may insure several items of that type, so
301	// a rule speaks for the damage if it applies to any of them.
302	const governs = (rule: ReimbursementRule, damagedItems: Item[]): boolean =>
303	  damagedItems.some(rule.appliesTo);
304	
305	// No rule matching means nothing about the item argues for paying less than in
306	// full. An item MHPCO has no record of insuring matches no rule either, and so
307	// is reimbursed in full by the same default.
308	const reimbursementPercentFor = (damagedItems: Item[]): number =>
309	  REIMBURSEMENT_RULES.find((rule) => governs(rule, damagedItems))?.percent ??
310	  FULL_REIMBURSEMENT_PERCENT;
311	
312	// A damage names an item type; the policy knows what it insured under that
313	// name, and the item's nature decides how much of the loss is met.
314	const insuredItemsOfType = (policy: Policy, itemType: string): Item[] =>
315	  policy.items.filter((item) => item.type === itemType);
316	
317	const reimbursementFor = (damage: Damage, policy: Policy): number =>
318	  applyPercent(
319	    damage.amount,
320	    reimbursementPercentFor(insuredItemsOfType(policy, damage.itemType)),
321	  );
322	
323	// An incident's damages are reimbursed one by one, then totalled before the
324	// deductible is taken, so the deductible falls once on the event rather than
325	// once per damaged item.
326	const reimbursementTotalOf = (incident: Incident, policy: Policy): number =>
327	  incident.damages.reduce(
328	    (total, damage) => total + reimbursementFor(damage, policy),
329	    0,
330	  );
331	
332	// The deductible reduces the payout, it never turns it into a charge: a loss
333	// smaller than the deductible is simply not paid, rather than billed back.
334	const netOfDeductible = (reimbursement: number): number =>
335	  Math.max(reimbursement - DEDUCTIBLE, NO_PAYOUT);
336	
337	// However great the loss, a policy pays out only what it has left to give, and
338	// a payout draws the cap down by exactly what was paid.
339	const payableUnder = (policy: Policy, reimbursement: number): number =>
340	  Math.min(netOfDeductible(reimbursement), policy.remainingCap);
341	
342	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
343	  const payout = payableUnder(
344	    policy,
345	    reimbursementTotalOf(step.incident, policy),
346	  );
347	  return { payout, remainingCap: policy.remainingCap - payout };
348	};
349	
350	// Steps are processed in order because each one depends on what came before: a
351	// quote's standing depends on how many contracts precede it, and a claim draws
352	// down the cap its policy has left. Both are carried explicitly as the policies
353	// map rather than mutated in place, so a step's effect on later steps is
354	// visible in what it returns.
355	interface Ledger {
356	  policies: Map<number, Policy>;
357	  results: StepResult[];
358	}
359	
360	const withPolicy = (
361	  policies: Map<number, Policy>,
362	  policyNumber: number,
363	  policy: Policy,
364	): Map<number, Policy> => new Map(policies).set(policyNumber, policy);
365	
366	// Every step settles the same way: it produces one result, and it leaves the
367	// policies it touched in whatever state that result implies. Saying so once
368	// keeps the two kinds of step from drifting apart in how they are recorded.
369	interface Settlement {
370	  policies: Map<number, Policy>;
371	  result: StepResult;
372	}
373	
374	// A quote opens a policy, numbered by its own position in the scenario — that
375	// number is what a later claim names to draw on this cover.
376	const settleQuote = (
377	  policies: Map<number, Policy>,
378	  step: QuoteStep,
379	  policyNumber: number,
380	  customer: Customer,
381	): Settlement => ({
382	  policies: withPolicy(policies, policyNumber, policyFor(step.items)),
383	  result: quote(step, { customer, isFirstContract: policyNumber === 0 }),
384	});
385	
386	const policyNamedBy = (
387	  policies: Map<number, Policy>,
388	  step: ClaimStep,
389	): Policy => {
390	  const policy = policies.get(step.policy);
391	  if (policy === undefined) {
392	    throw new Error(`Claim refers to unknown policy ${step.policy}`);
393	  }
394	  return policy;
395	};
396	
397	// A claim draws the named policy's cap down by what it paid, and writes the
398	// drawn-down policy back so the next claim on it sees the smaller cap.
399	const settleClaim = (
400	  policies: Map<number, Policy>,
401	  step: ClaimStep,
402	): Settlement => {
403	  const policy = policyNamedBy(policies, step);
404	  const result = claim(step, policy);
405	  return {
406	    policies: withPolicy(policies, step.policy, {
407	      ...policy,
408	      remainingCap: result.remainingCap,
409	    }),
410	    result,
411	  };
412	};
413	
414	const applyStep = (
415	  { policies, results }: Ledger,
416	  step: Step,
417	  index: number,
418	  customer: Customer,
419	): Ledger => {
420	  const settlement =
421	    step.op === "quote"
422	      ? settleQuote(policies, step, index, customer)
423	      : settleClaim(policies, step);
424	  return {
425	    policies: settlement.policies,
426	    results: [...results, settlement.result],
427	  };
428	};
429	
430	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
431	  const { results } = steps.reduce<Ledger>(
432	    (ledger, step, index) => applyStep(ledger, step, index, customer),
433	    { policies: new Map(), results: [] },
434	  );
435	  return { results };
436	};
